# Studyo 0.5.57 yamasi: Gemini zaman asimi/baglanti hatasi yeniden denenir (istek suresi 240 sn); 10 denemede cevap yoksa kitap
# denetimsiz surmez, 30 dk sonra yeniden denenir (en cok 8 kez). 0.5.56 uzerine. Kod klasorunde: python3 studyo_0557_yama.py
import base64, hashlib, os, sys, zlib
D = [
    ('kutuphane/yz.py', '3f1f135835141bcf976b45f05fd6d2ef', 'b7deb15e58cfcddf7dc031b5b9ad9361',
     ''),
    ('kutuphane/depo.py', '6ca9fbbb03b85a805840552fd0e07daa', '8d1799bdb5042b814a1c9d98afc51e6f',
     ''),
    ('kutuphane/main.py', 'cb39f583490168d0944adb1a37449717', '3426b1789ec6f926e90a7b7031400ffc',
     ''),
    ('tests/test_0557.py', None, 'c3f602b6e24a965bbfe443b46e75c9ff',
     ''),
]
md5 = lambda p: hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.exists(p) else None
for yol, eski, yeni, _ in D:
    m = md5(yol)
    if m not in (eski, yeni):
        print('HATA:', yol, 'beklenmeyen icerik (md5', m, ') - hicbir dosya degistirilmedi'); sys.exit(1)
for yol, eski, yeni, veri in D:
    if md5(yol) == yeni:
        print('ATLANDI (zaten yeni):', yol); continue
    icerik = zlib.decompress(base64.b64decode(veri))
    assert hashlib.md5(icerik).hexdigest() == yeni
    os.makedirs(os.path.dirname(yol) or '.', exist_ok=True)
    open(yol, 'wb').write(icerik)
    print('YAZILDI:', yol, yeni)
print('TAMAM')
